def avg(xs):
    return sum(xs) / len(xs)


def median(xs):
    """Return the median of xs."""
    ordered = sorted(xs)
    n = len(ordered)
    if n == 0:
        raise ValueError("median() arg is an empty sequence")
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

